export function divide_all(xs: number[], ys: number[]): number[] {
  for (let i = 0; i < ys.length; i++) {
    if (ys[i] === 0) {
      throw new Error(`division by zero at index ${i}`);
    }
  }
  const out: number[] = [];
  for (let i = 0; i < xs.length; i++) {
    out.push(Math.trunc(xs[i] / ys[i]) || 0);
  }
  return out;
}
